INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-08-26', 'art', 'nsfw', 'Skulldragon Bed', 'skulldragon-bed', 'Skulldragon Bed', replace('Something I wanted to draw with skulldragon Jesper. Thought it''d be a cute idea if me and my partner used him as a bed.\n\nI still use this as my banner on some adult social media platforms.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) EX\n\nDate Completed: August 26, 2024\n\nTime Spent: 8 hours 44 minutes\n\nTimelapse:\n\n<video controls preload="metadata">\n    <source src="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/26/tl.mp4" type="video/mp4">\n    Your browser does not support the video tag. <a href="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/26/tl.mp4">Download</a>\n</video>','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/26/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/26/img.png', NULL, NULL, 0, 1, '["personal","art","skulldragon","jesper-foster","logan-foster","reese","oonracc","redrift","raccoon","cat","monster","clip-studio-paint-ex","fatfur","rendered","size-difference","scene","furry","fullbody","character"]', '2024-08-26T00:00:00Z');
INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-08-08', 'art', 'nsfw', 'Jesper Skulldragon Design Sketch', 'jsd-design-sketch', 'Jesper Skulldragon Design Sketch', replace('Skulldragon species created by [**CamuuShamuu**](https://furaffinity.net/user/CamuuShamuu)\n\nI thought I''d make a skulldragon variant of Jesper since he already has a skull for a mask anyways, and I thought it''d be funny to see what he''d look like if he put on the wrong mask waking up in the morning.\n\nSince he''s got heterochromia in his eyes, I decided to make it so his magic aura stuff is like the two colors blended. So that means he''s orange!\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) EX\n\nDate Completed: August 8, 2024\n\nTime Spent: 2 hours 30 minutes\n\nTimelapse:\n\n<video controls preload="metadata">\n    <source src="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/08/tl.mp4" type="video/mp4">\n    Your browser does not support the video tag. <a href="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/08/tl.mp4">Download</a>\n</video>','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/08/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/08/08/img.png', NULL, 'Reference', 0, 1, '["personal","art","jesper-foster","skulldragon","cat","monster","raccoon","character","clip-studio-paint-ex","concept","fatfur","flat-color","fullbody","furry","redrift"]', '2024-08-08T00:00:00Z');
INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-07-05', 'art', 'nsfw', 'Longing for the Past', 'longing-for-the-past', 'Longing for the Past', replace('Decided I''d try something lore-heavy for once. Pun entirely intended.\n\nThis is something I have planned to take place in Logan''s story once he reaches his middle ages.\n\n_"Oof... usually he comes back within the same month he leaves, but... it''s been years... where did he go...?"_\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) EX\n\nDate Completed: July 5, 2024\n\nTime Spent: 10 hours 32 minutes\n\nTimelapse:\n\n<video controls preload="metadata">\n    <source src="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/07/05/tl.mp4" type="video/mp4">\n    Your browser does not support the video tag. <a href="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/07/05/tl.mp4">Download</a>\n</video>','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/07/05/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/07/05/img.png', NULL, 'Rendered', 0, 1, '["personal","art","background","character","clip-studio-paint-ex","fatfur","fullbody","furry","logan-foster","raccoon","redrift","rendered","scene"]', '2024-07-05T00:00:00Z');
INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-05-02', 'art', 'nsfw', 'Kybu and Logan Vore', 'kybu-and-logan-vore', 'Kybu and Logan Vore', replace('This was my first time drawing vore. Admittedly I was more focused on making Kybu a massive blob than I was trying to make this look like vore. But hey. It exists.\n\nDrew this as a gift for my friend [KybuTheRaptor](https://www.instagram.com/kybutheraptor/) soon after we both found out we were into fat furs and by extension vore.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) EX\n\nDate Completed: May 2, 2024\n\nTime Spent: 3 hours 42 minutes','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/05/02/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/05/02/img.png', NULL, 'Shaded', 0, 1, '["personal","art","kybu","raptor","vore","character","clip-studio-paint-ex","fatfur","fullbody","furry","gift","logan-foster","raccoon","redrift","shaded","size-difference"]', '2024-05-02T00:00:00Z');
