INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-03-12', 'art', 'nsfw', 'FurAffinity Banner', 'fa-banner', 'FurAffinity Banner', replace('This is a banner I created for my FurAffinity account, back when I used Logan as my mascot for both SFW and NSFW works. I have since removed it.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) PRO\n\nDate Completed: March 12, 2024\n\nTime Spent: 2 hours 22 minutes\n\nTimelapse:\n\n<video controls preload="metadata">\n    <source src="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/03/12/tl.mp4" type="video/mp4">\n    Your browser does not support the video tag. <a href="https://media.raccstarlogan.com/nsfw/portfolio/art/2024/03/12/tl.mp4">Download</a>\n</video>','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/03/12/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/03/12/img.png', NULL, 'Rendered', 0, 1, '["personal","art","clip-studio-paint-pro","character","fatfur","headshot","banner","logan-foster","raccoon","redrift","rendered"]', '2024-03-12T00:00:00Z');
INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2024-02-20', 'art', 'nsfw', 'Fatso Breaks the Scale', 'fatso-breaks-the-scale', 'Fatso Breaks the Scale', replace('Oops! Logan seems to have gone overboard with his weight gain. I guess he''s gonna need a new scale sometime soon, if he can find one that can contain him that is! It''s crazy just how much he gained in such a short ammount of time.\n\nAnother thing I wanted to do to show off contrast, as well as a slight bit of world-building and environmental storytelling. Because why not.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) PRO\n\nDate Completed: February 2, 2024\n\nTime Spent: 10 hours 9 minutes','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/02/20/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2024/02/20/img.png', NULL, 'Rendered', 0, 1, '["personal","art","character","clip-studio-paint-pro","fatfur","fullbody","furry","logan-foster","raccoon","redrift","rendered","scene"]', '2024-02-20T00:00:00Z');
INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2023-12-09', 'art', 'nsfw', 'Clashing Interests', 'clashing-interests', 'Clashing Interests', replace('Jesper doesn''t really like, agree with, or really understand Logan''s "hobbies." Despite this, Logan bloats himself up with lard any chance that he can get. It just so happened that Jesper walked in this time.\n\nI wanted to try and do a contrast thing, and so I did this. It''s both a size contrast and a sanity contrast.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) PRO\n\nDate Completed: December 9, 2023\n\nTime Spent: Unknown\n\nTimelapse:\n\n<video controls preload="metadata">\n    <source src="https://media.raccstarlogan.com/nsfw/portfolio/art/2023/12/09/tl.mp4" type="video/mp4">\n    Your browser does not support the video tag. <a href="https://media.raccstarlogan.com/nsfw/portfolio/art/2023/12/09/tl.mp4">Download</a>\n</video>','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2023/12/09/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2023/12/09/img.png', NULL, 'Rendered', 0, 1, '["personal","art","cat","character","clip-studio-paint-pro","fatfur","fullbody","furry","logan-foster","jesper-foster","monster","raccoon","redrift","size-difference"]', '2023-12-09T00:00:00Z');
