INSERT INTO portfolio_items (id, kind, visibility, title, slug, summary, description, thumbnail_url, logo_url, media_url, external_url, commission_type, is_commission, is_personal, tags_json, published_at) VALUES ('NSFW-P-A-2023-07-01', 'art', 'nsfw', '[Art Trade] Geo Blob', 'art-trade-geo-blob', '[Art Trade] Geo Blob', replace('This is my part of an art trade I did with FurAffinity user GeoDergArt2001, who has since deactivated his account unfortunately.\n\nThis was my first time drawing a skulldragon.\n\nSoftware Used: [Clip Studio Paint](https://www.clipstudio.net/en/purchase/) PRO\n\nDate Completed: July 1, 2023\n\nTime Spent: Unknown','\n',char(10)), 'https://media.raccstarlogan.com/nsfw/portfolio/art/2023/07/01/thumb.jpg', NULL, 'https://media.raccstarlogan.com/nsfw/portfolio/art/2023/07/01/img.png', NULL, 'Rendered', 1, 0, '["personal","art","skulldragon","geo","character","clip-studio-paint-pro","commissions","fatfur","fullbody","furry","trade"]', '2023-07-01T00:00:00Z');
